.easy-form{margin-top:34px;padding:28px;border:1px solid var(--border);border-radius:20px;background:#fff}.easy-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.easy-grid label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:600}.easy-grid input,.easy-grid select{width:100%;padding:12px 13px;border:1px solid var(--border);border-radius:9px;background:#fff;font:inherit}.easy-full{grid-column:1/-1}.easy-check{display:flex!important;flex-direction:row!important;align-items:flex-start;gap:10px!important;font-weight:400!important;line-height:1.55}.easy-check input{width:auto;margin-top:4px}.easy-alert{margin:0 0 22px;padding:16px 18px;border-radius:12px}.easy-error{border:1px solid #dca8a8;background:#fff5f5;color:#842929}.easy-success{border:1px solid #9bc8ab;background:#f1faf4;color:#1d6b39}.easy-actions{margin-top:22px}.easy-hp{position:absolute;left:-9999px}
